// How far an AI assistant has got with a card (docs/specs/026-plan/items.md "Progress on the card"): read from what it
// already writes, its Generated by AI comments and its moves, never anything stored for it. Pure, so the panel's line
// and its tests read the same words.
import {
  itemAssistantOf,
  itemStatus,
  itemStatusSince,
  type Item,
  type ItemAssistant,
} from '@liveplanner/items';
import type { CardThread } from '@liveplanner/project';

// The most of a note the line repeats.
export const ASSISTANT_NOTE_MAX = 80;

export type AssistantProgressLine = {
  assistant: ItemAssistant;
  // "In Progress for 2 hours", or null for a card in no column.
  column: string | null;
  // Its newest note on the card: the first line, cut, and when.
  note: { text: string; at: number } | null;
};

// "5 minutes", "2 hours", "3 days": how long, in the largest whole unit.
export function spanWords(ms: number): string {
  const minutes = Math.floor(Math.max(0, ms) / 60_000);
  const unit = (n: number, word: string) => `${n} ${word}${n === 1 ? '' : 's'}`;
  if (minutes < 1) return 'under a minute';
  if (minutes < 60) return unit(minutes, 'minute');
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return unit(hours, 'hour');
  return unit(Math.floor(hours / 24), 'day');
}

const firstLine = (text: string): string => {
  const line = text.trim().split('\n', 1)[0]!.trim();
  return line.length > ASSISTANT_NOTE_MAX ? `${line.slice(0, ASSISTANT_NOTE_MAX - 1)}…` : line;
};

export function assistantProgress(
  item: Item,
  threads: readonly CardThread[],
  columnName: (status: string) => string | undefined,
  now: number,
): AssistantProgressLine | null {
  const assistant = itemAssistantOf(item);
  if (!assistant) return null;
  // Its person's agent comments: comments carry their author's name, never their id, to anyone but the author.
  const by = assistant.assistant.person.name;
  let note: AssistantProgressLine['note'] = null;
  for (const thread of threads)
    for (const c of thread.comments)
      if (c.ai && c.authorName === by && c.text.trim() && (!note || c.createdAt > note.at))
        note = { text: c.text, at: c.createdAt };
  const status = itemStatus(item);
  const name = status ? columnName(status) : undefined;
  return {
    assistant,
    column: name ? `${name} for ${spanWords(now - itemStatusSince(item))}` : null,
    note: note ? { text: firstLine(note.text), at: note.at } : null,
  };
}
